  )(bytes).pipe(
    Effect.mapError(
      () =>
        new CodexSubscriptionAuthError({
          operation: "completeLogin",
          reason: "cryptoFailure",
          message: "Unable to encode the OAuth credential revision.",
        })
    )
  );

  return yield* Schema.decodeUnknownEffect(CodexOAuthCredentialRevision)(
    encoded
  ).pipe(
    Effect.mapError(
      () =>
        new CodexSubscriptionAuthError({
